/**
 * Push notification handler for Service Worker
 * Imported by the SW generated by vite-plugin-pwa via importScripts
 */

// Handle push events
self.addEventListener('push', (event) => {
  let data = {
    title: 'Gardina',
    body: 'Жаңа хабарлама',
    icon: '/pwa-192x192.png',
    badge: '/badge-72x72.png',
    data: { url: '/' }
  };

  try {
    if (event.data) {
      const payload = event.data.json();
      data = { ...data, ...payload };
    }
  } catch (e) {
    if (event.data) data.body = event.data.text();
  }

  const options = {
    body: data.body,
    icon: data.icon || '/pwa-192x192.png',
    badge: data.badge || '/badge-72x72.png',
    vibrate: [200, 100, 200],
    tag: data.tag || 'gardina-notification',
    renotify: true,
    requireInteraction: false,
    data: data.data || { url: '/' },
    actions: [
      { action: 'open', title: 'Ашу' },
      { action: 'close', title: 'Жабу' }
    ]
  };

  event.waitUntil(
    self.registration.showNotification(data.title, options)
  );
});

// Handle notification click
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  if (event.action === 'close') return;

  const urlToOpen = event.notification.data?.url || '/';

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if (client.url.includes(self.location.origin) && 'focus' in client) {
          client.focus();
          if (client.navigate) client.navigate(urlToOpen);
          return;
        }
      }
      if (clients.openWindow) return clients.openWindow(urlToOpen);
    })
  );
});

// Handle push subscription change (browser refreshes the subscription automatically)
// We can't use auth token directly in SW, so we tell the app to re-subscribe
self.addEventListener('pushsubscriptionchange', (event) => {
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      if (clientList.length > 0) {
        // Notify the app to re-subscribe using its auth token
        clientList.forEach(client => {
          client.postMessage({ type: 'PUSH_SUBSCRIPTION_CHANGED' });
        });
      }
    })
  );
});

console.log('[SW] Push handler loaded');
